  'fechar-com': () => { const l = db.equipe.map(comissaoDe), tot = l.reduce((s, c) => s + c.liquido, 0), mes = new Date().toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }); if (db.fechCom.some((f) => f.mes === mes)) { recado(`O mês de ${mes} já foi fechado.`); return; } if (!confirm(`Fechar as comissões de ${mes}? Total a pagar: ${R2(tot)}. Os vales em aberto serão descontados.`)) return; db.fechCom.push({ mes, total: Math.round(tot * 100) / 100, em: hojeISO(), linhas: l.map((c) => [c.p.nome, c.liquido]) }); db.vales.forEach((v) => { v.descontado = true; }); anota(`fechou as comissões de ${mes}: ${R2(tot)}`); salva(); monta(); recado('Mês fechado. A planilha pode ser baixada para pagar.'); },
