  'nova-pro': () => formA('Nova profissional', `<label class="cp">Nome<input name="n" required maxlength="40"></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="cp">Casa<select name="u">${opUn(db.un !== 'todas' ? db.un : '')}</select></label><label class="cp">Área<input name="a" maxlength="40" placeholder="Escova e corte"></label></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="cp">Meta do mês (R$)<input name="m" inputmode="decimal" required></label><label class="cp">Comissão de serviço (%)<input name="c" type="number" min="0" max="80" value="40"></label></div>`, 'Cadastrar', (f) => { const nome = String(f.get('n')).trim(), meta = nv(f.get('m')), com = Number(f.get('c')); if (!nome) return 'Informe o nome.'; if (!(meta > 0)) return 'Informe a meta.'; if (!(com >= 0 && com <= 80)) return 'Comissão entre 0 e 80%.'; db.equipe.push({ id: `e${Date.now().toString(36)}`, nome, un: f.get('u'), area: String(f.get('a') || '').trim(), meta, real: 0, ticket: 0, prod: 0, com, comProd: 10 }); anota(`cadastrou ${nome} na equipe`); }),
  'nova-ficha': () => formA('Novo serviço na ficha técnica', '<label class="cp">Serviço<input name="n" required maxlength="40"></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="cp">Preço (R$)<input name="p" inputmode="decimal" required></label><label class="cp">Minutos<input name="m" type="number" min="10" max="480" value="60"></label></div>', 'Criar', (f) => { const n = String(f.get('n')).trim(), p = nv(f.get('p')); if (!n || !(p > 0)) return 'Nome e preço.'; db.fichas.push({ id: `f${Date.now().toString(36)}`, serv: n, preco: p, min: Number(f.get('m')) || 60, insumos: [] }); anota(`criou a ficha de ${n}`); }),
